# aplicar-v72-orders-e-financeiro-separados.ps1
# Corrige a organizacao:
#
# /admin/orders   = tela antiga de pedidos
# /admin/finance  = tela financeira com graficos, IR/contador e exportacoes
#
# Se /admin/orders ainda estiver com a tela financeira da v71,
# este script tenta restaurar automaticamente o backup antigo page.tsx.bak-v71-*.
#
# Tambem adiciona o link "Financeiro" no menu admin/super admin.

$ErrorActionPreference = "Stop"

$Root = Get-Location
$Stamp = Get-Date -Format "yyyyMMdd-HHmmss"

function Write-TextBase64File($RelativePath, $Base64Content) {
  $Target = Join-Path $Root $RelativePath
  $TargetDir = Split-Path $Target -Parent

  if (-not (Test-Path $TargetDir)) {
    New-Item -ItemType Directory -Path $TargetDir -Force | Out-Null
  }

  if (Test-Path $Target) {
    $Backup = "$Target.bak-v72-$Stamp"
    Copy-Item $Target $Backup -Force
    Write-Host "Backup criado: $Backup" -ForegroundColor DarkGray
  }

  $Content = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Base64Content))
  Set-Content -Path $Target -Value $Content -Encoding UTF8
  Write-Host "Atualizado: $RelativePath" -ForegroundColor Green
}

function Restore-OrdersIfNeeded() {
  $OrdersPath = Join-Path $Root "apps\web\src\app\admin\orders\page.tsx"
  $OrdersDir = Split-Path $OrdersPath -Parent

  if (-not (Test-Path $OrdersPath)) {
    Write-Host "Aviso: /admin/orders nao encontrado para restaurar." -ForegroundColor Yellow
    return
  }

  $Current = Get-Content $OrdersPath -Raw

  $LooksLikeV71Finance =
    ($Current -match "Financeiro, pedidos e relatório") -or
    ($Current -match "AdminFinancePage") -or
    ($Current -match "relatório para contador") -or
    ($Current -match "Exportar relatório IR/contador")

  if (-not $LooksLikeV71Finance) {
    Write-Host "/admin/orders parece estar como tela de pedidos. Nao vou mexer nela." -ForegroundColor Green
    return
  }

  Write-Host "/admin/orders ainda parece estar com a tela financeira. Tentando restaurar backup antigo..." -ForegroundColor Yellow

  $Backups = Get-ChildItem -Path $OrdersDir -Filter "page.tsx.bak-v71-*" -File -ErrorAction SilentlyContinue |
    Sort-Object LastWriteTime -Descending

  if ($Backups -and $Backups.Count -gt 0) {
    $CurrentBackup = "$OrdersPath.bak-v72-financeiro-removido-$Stamp"
    Copy-Item $OrdersPath $CurrentBackup -Force
    Write-Host "Backup da tela financeira atual criado: $CurrentBackup" -ForegroundColor DarkGray

    Copy-Item $Backups[0].FullName $OrdersPath -Force
    Write-Host "Tela antiga de pedidos restaurada de: $($Backups[0].FullName)" -ForegroundColor Green
    return
  }

  Write-Host "Nao encontrei backup page.tsx.bak-v71-*." -ForegroundColor Yellow
  Write-Host "Tentando restaurar via Git..." -ForegroundColor Cyan

  git checkout -- "apps/web/src/app/admin/orders/page.tsx"

  if ($LASTEXITCODE -eq 0) {
    Write-Host "Tela antiga de pedidos restaurada via Git." -ForegroundColor Green
    return
  }

  Write-Host "Nao consegui restaurar /admin/orders automaticamente." -ForegroundColor Red
  Write-Host "A tela financeira foi criada separada em /admin/finance mesmo assim." -ForegroundColor Yellow
}

function Patch-HeaderFinanceLink() {
  $HeaderPath = Join-Path $Root "apps\web\src\components\customer\CustomerHeader.tsx"

  if (-not (Test-Path $HeaderPath)) {
    Write-Host "Aviso: CustomerHeader.tsx nao encontrado. Link Financeiro nao adicionado." -ForegroundColor Yellow
    return
  }

  $Content = Get-Content $HeaderPath -Raw
  $Original = $Content

  if ($Content -notmatch 'href:\s*"/admin/finance"') {
    if ($Content -match '\{\s*label:\s*"Pedidos"\s*,\s*href:\s*"/admin/orders"\s*\},') {
      $Content = [regex]::Replace(
        $Content,
        '\{\s*label:\s*"Pedidos"\s*,\s*href:\s*"/admin/orders"\s*\},',
        '{ label: "Pedidos", href: "/admin/orders" },' + "`r`n" + '    { label: "Financeiro", href: "/admin/finance" },',
        1
      )
    } elseif ($Content -match '\{\s*label:\s*"Eventos"\s*,\s*href:\s*"/admin/events"\s*\},') {
      $Content = [regex]::Replace(
        $Content,
        '\{\s*label:\s*"Eventos"\s*,\s*href:\s*"/admin/events"\s*\},',
        '{ label: "Eventos", href: "/admin/events" },' + "`r`n" + '    { label: "Financeiro", href: "/admin/finance" },',
        1
      )
    } else {
      Write-Host "Nao encontrei ponto claro para inserir Financeiro no header." -ForegroundColor Yellow
    }
  }

  if ($Content -ne $Original) {
    $Backup = "$HeaderPath.bak-v72-$Stamp"
    Copy-Item $HeaderPath $Backup -Force
    Set-Content -Path $HeaderPath -Value $Content -Encoding UTF8
    Write-Host "Header atualizado com link Financeiro." -ForegroundColor Green
  } else {
    Write-Host "Header sem alteracoes." -ForegroundColor Yellow
  }
}

Write-Host "Aplicando v72 - Orders e Financeiro separados..." -ForegroundColor Cyan

$FinancePageBase64 = ""

Restore-OrdersIfNeeded
Write-TextBase64File "apps\web\src\app\admin\finance\page.tsx" $FinancePageBase64
Patch-HeaderFinanceLink

Write-Host ""
Write-Host "v72 aplicada com sucesso." -ForegroundColor Green
Write-Host ""
Write-Host "Agora fica assim:" -ForegroundColor Cyan
Write-Host "- /admin/orders  = tela de pedidos" -ForegroundColor Cyan
Write-Host "- /admin/finance = tela financeira separada" -ForegroundColor Cyan
Write-Host ""
Write-Host "Reinicie o WEB:" -ForegroundColor Cyan
Write-Host 'cd "C:\Users\march\OneDrive\Área de Trabalho\plataforma-ingressos\apps\web"' -ForegroundColor Cyan
Write-Host "npm run dev" -ForegroundColor Cyan
